agent_sql:
SELECT SUM(effective_precipitation_mgd) AS effective_precipitation_mgd
FROM dashboard_huc4_year
WHERE watershed = 'Southern Coastal' AND year = 2012;

SELECT COUNT(DISTINCT huc12) AS distinct_huc12_positive_irrigation
FROM irrigation_huc12_annual
WHERE irrigation_mgd > 0;

SELECT w.watershed,
       COALESCE(pub.annual_avg_use_mgd,0) - COALESCE(irr.annual_avg_use_mgd,0) AS public_minus_irrigation
FROM (
  SELECT DISTINCT watershed FROM water_huc4_annual_category WHERE year=2020
) w
LEFT JOIN (
  SELECT watershed, annual_avg_use_mgd FROM water_huc4_annual_category WHERE year=2020 AND category='public-supply'
) pub ON w.watershed = pub.watershed
LEFT JOIN (
  SELECT watershed, annual_avg_use_mgd FROM water_huc4_annual_category WHERE year=2020 AND category='irrigation'
) irr ON w.watershed = irr.watershed
ORDER BY w.watershed;
